def model(x, q, kind):
    (a, b, c, d) = x.T
    (bias, amp, k, h, t, c1, c2, v, mix) = q[:9]
    z = np.maximum(a - t, 0)
    power = kind % 4 + 1
    if kind // 4 == 0:
        cross = (c1 * c + c2 * c * c) / (1 + v * c * c)
    if kind // 4 == 1:
        cross = c1 * np.tanh(v * c) + c2 * c * c
    if kind // 4 == 2:
        cross = c1 * c + c2 * c * c / (1 + v * c * c)
    if kind // 4 == 3:
        cross = c1 * c / (1 + v * c * c) + c2 * c * c
    if kind // 4 == 4:
        cross = (c1 * c + c2 * c * c) / (1 + v * (a * a + c * c))
    if kind // 4 == 5:
        cross = c1 * c + c2 * c * c
    if kind // 4 == 6:
        cross = (c1 * c + c2 * c * c) / (1 + v * (a + c) ** 2)
    if kind // 4 == 7:
        cross = (c1 * c + c2 * c * c) / (1 + v * (a - c) ** 2)
    if kind // 4 == 8:
        cross = c1 * c / (1 + v * c * c) + c2 * c * c / (1 + q[9] * c * c)
    return bias + amp * np.tanh(k * a) + h * z ** power + cross + mix * a * c

def _operator(st):
    from scipy import sparse
    (nx, ny) = (st['nx'], st['ny'])
    ax = _axis(st['kappa_x'], st['vel_x'], st['Lx'] / (nx - 1))
